1	//! Qwen3's [`ModelLine`] implementation: config probing, the Qwen3-exclusive
2	//! CLI section, cross-flag rules, and launch-option assembly. The server
3	//! binary only sees `&MODEL_LINE`.
4	
5	use std::collections::BTreeSet;
6	use std::path::PathBuf;
7	
8	use clap::Args as ClapArgs;
9	use clap::FromArgMatches;
10	use pegainfer_frontend::engine::LaunchedEngine;
11	use pegainfer_frontend::model_line::ArgRequirement;
12	use pegainfer_frontend::model_line::CliDecodeOverlap;
13	use pegainfer_frontend::model_line::CliError;
14	use pegainfer_frontend::model_line::LaunchContext;
15	use pegainfer_frontend::model_line::ModelLine;
16	use pegainfer_frontend::model_line::ServePlan;
17	use pegainfer_frontend::vllm::LoraModule;
18	use pegainfer_frontend::vllm::parse_lora_modules_arg;
19	
20	use crate::DecodeOverlap;
21	use crate::Qwen3LaunchOptions;
22	use crate::Qwen3LoraOptions;
23	use crate::Qwen3MemoryOptions;
24	use crate::Qwen3OffloadOptions;
25	use crate::Qwen3P2pOptions;
26	use crate::Qwen3VllmCompatOptions;
27	
28	pub static MODEL_LINE: Qwen3Line = Qwen3Line;
29	
30	pub struct Qwen3Line;
31	
32	// Qwen3-exclusive CLI flags. Shared flags (`--tp-size`, `--kv-offload`, …)
33	// live in `SharedArgs`. (Regular comment: a doc comment would override the
34	// command about via clap's augment.)
35	#[derive(ClapArgs)]
36	#[allow(clippy::struct_excessive_bools)] // independent CLI flags, not a state machine
37	struct Qwen3Cli {
38	    /// Enable Qwen3 LoRA serving mode.
39	    #[arg(long, default_value_t = false)]
40	    enable_lora: bool,
41	
42	    /// LoRA modules to load at startup. Accepts vLLM-style `name=path`, JSON
43	    /// object, or JSON list object entries with `name` and `path`.
44	    #[arg(long = "lora-modules", value_parser = parse_lora_modules_arg)]
45	    lora_modules: Vec<LoraModule>,
46	
47	    /// Maximum number of resident LoRA adapters in Qwen3 LoRA mode.
48	    #[arg(long = "max-loras", default_value_t = Qwen3LoraOptions::DEFAULT_MAX_LORAS)]
49	    max_loras: usize,
50	
51	    /// Maximum supported LoRA rank in Qwen3 LoRA mode.
52	    #[arg(long = "max-lora-rank", default_value_t = Qwen3LoraOptions::DEFAULT_MAX_LORA_RANK, value_parser = parse_max_lora_rank_arg)]
53	    max_lora_rank: usize,
54	
55	    /// P/D prefill role: barrier each request's KV saves (host tier +
56	    /// MetaServer registration) before its final token event, so this
57	    /// instance's HTTP response doubles as the KV-ready signal a router can
58	    /// act on. Leave off on decode instances.
59	    #[arg(long, default_value_t = false)]
60	    kv_p2p_flush_on_finish: bool,
61	
62	    /// P/D decode role with a vLLM prefill peer: the shared PYTHONHASHSEED
63	    /// value set on every vLLM prefill process. Switches offload query keys to
64	    /// vLLM's prefix-cache hash scheme (requires the P side to run
65	    /// --prefix-caching-hash-algo xxhash_cbor) and makes a cold request wait
66	    /// out the producer's registration tail instead of prefilling locally.
67	    /// Requires --kv-pd-vllm-namespace and the P2P mesh flags.
68	    #[arg(long, value_parser = parse_pythonhashseed)]
69	    kv_pd_vllm_seed: Option<String>,
70	
71	    /// The vLLM prefill peer's pegaflow-connector namespace (an 8-hex digest
72	    /// the connector logs at startup as `namespace=...`). Both sides must
73	    /// address the same content domain. The digest carries no model identity:
74	    /// pointing a decode node at a different model's namespace (same
75	    /// tokenizer, same geometry class) silently cross-loads foreign KV.
76	    #[arg(long, value_parser = parse_pegaflow_namespace)]
77	    kv_pd_vllm_namespace: Option<String>,
78	
79	    /// Zero-hit wait window for --kv-pd-vllm-seed mode, in milliseconds: how
80	    /// long a cold request keeps re-querying before giving up on the expected
81	    /// remote KV and prefilling locally. Must stay below the executor's 15s
82	    /// remote-fetch deadline (enforced at startup).
83	    #[arg(long, default_value_t = 5000)]
84	    kv_pd_miss_wait_ms: u64,
85	
86	    /// Fraction of total GPU memory the Qwen3 instance may use. The KV cache is
87	    /// sized from this budget after startup profiling accounts for weights,
88	    /// runtime buffers, activation peak, margin, and (single-GPU only) CUDA-graph
89	    /// capture; tensor parallelism runs decode eagerly (no graph).
90	    #[arg(long, default_value_t = crate::DEFAULT_GPU_MEMORY_UTILIZATION)]
91	    gpu_memory_utilization: f64,
92	
93	    /// Additional Qwen3 GPU memory to hold back after profile-based KV sizing,
94	    /// in MiB. Covers allocator fragmentation and small unprofiled drift.
95	    #[arg(long, default_value_t = (crate::DEFAULT_KV_CACHE_MEMORY_MARGIN_BYTES >> 20) as usize)]
96	    kv_cache_memory_margin_mib: usize,
97	
98	    /// KV cache page (block) size in tokens. FlashInfer's paged attention only
99	    /// accepts a restricted set; 16 (default) or 64. Larger pages cut block
100	    /// bookkeeping overhead at the cost of coarser-grained allocation.
101	    #[arg(long, default_value_t = crate::DEFAULT_KV_PAGE_SIZE)]
102	    kv_page_size: usize,
103	
104	    /// Enable single-GPU Qwen3 batch-invariant serving by pinning the numeric paths and cutting
105	    /// each prompt's prefill chunks on its own grid. Off by default. Requires `--no-prefix-cache`;
106	    /// incompatible with `--kv-offload`, which keeps prefix matching on regardless.
107	    #[arg(long, default_value_t = false)]
108	    batch_invariant: bool,
109	
110	    /// EAGLE-3 drafter model path. A greedy request drafts while it is the only
111	    /// active request; larger batches decode plainly. Single-GPU only, not with
112	    /// --dflash-draft-model-path, --enable-lora, --kv-offload, --decode-overlap
113	    /// or --batch-invariant, and forces the prefix cache off.
114	    #[arg(long)]
115	    eagle3_draft_model_path: Option<PathBuf>,
116	}
117	
118	fn resolve_decode_overlap(overlap: CliDecodeOverlap, decode_sm_pct: u32) -> DecodeOverlap {
119	    match overlap {
120	        CliDecodeOverlap::Off => DecodeOverlap::Off,
121	        CliDecodeOverlap::Stream => DecodeOverlap::SharedSm,
122	        CliDecodeOverlap::GreenCtx => DecodeOverlap::GreenCtx {
123	            decode_pct: decode_sm_pct,
124	        },
125	    }
126	}
127	
128	fn cli(ctx: &LaunchContext<'_>) -> Qwen3Cli {
129	    Qwen3Cli::from_arg_matches(ctx.matches).expect("Qwen3Cli parses from the merged command")
130	}
131	
132	impl ModelLine for Qwen3Line {
133	    fn name(&self) -> &'static str {
134	        "Qwen3"
135	    }
136	
137	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
138	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
139	        if model_type != Some("qwen3") {
140	            return Err(format!("model_type {model_type:?} is not \"qwen3\""));
141	        }
142	        crate::probe_config_json(config).map_err(|error| error.to_string())
143	    }
144	
145	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
146	        Qwen3Cli::augment_args(cmd)
147	    }
148	
149	    fn consumed_shared_args(&self) -> &'static [&'static str] {
150	        &[
151	            "cuda_graph",
152	            "dump_graph_png",
153	            "device_ordinal",
154	            "tp_size",
155	            "kv_offload",
156	            "kv_offload_host_gib",
157	            "kv_offload_hugepages",
158	            "kv_p2p_metaserver_addr",
159	            "kv_p2p_advertise_addr",
160	            "kv_p2p_nics",
161	            "no_prefix_cache",
162	            "max_prefill_tokens",
163	            "dflash_draft_model_path",
164	            "decode_overlap",
165	            "decode_sm_pct",
166	        ]
167	    }
168	
169	    fn arg_requirements(&self) -> &'static [ArgRequirement] {
170	        &[
171	            ("kv_p2p_flush_on_finish", &["kv_p2p_metaserver_addr"]),
172	            (
173	                "kv_pd_vllm_seed",
174	                &["kv_p2p_metaserver_addr", "kv_pd_vllm_namespace"],
175	            ),
176	            ("kv_pd_vllm_namespace", &["kv_pd_vllm_seed"]),
177	            ("kv_pd_miss_wait_ms", &["kv_pd_vllm_seed"]),
178	        ]
179	    }
180	
181	    fn validate(
182	        &self,
183	        ctx: &LaunchContext<'_>,
184	        provided: &BTreeSet<String>,
185	    ) -> Result<(), CliError> {
186	        let cli = cli(ctx);
187	        let shared = ctx.shared;
188	        if !cli.enable_lora && !cli.lora_modules.is_empty() {
189	            return Err(CliError::rule("--lora-modules requires --enable-lora"));
190	        }
191	        if !cli.enable_lora
192	            && (provided.contains("max_loras") || provided.contains("max_lora_rank"))
193	        {
194	            return Err(CliError::rule(
195	                "--max-loras and --max-lora-rank require --enable-lora",
196	            ));
197	        }
198	        if shared.dump_graph_png.is_some() && cli.enable_lora {
199	            return Err(CliError::rule(
200	                "--dump-graph-png is not supported with --enable-lora (LoRA disables CUDA Graph)",
201	            ));
202	        }
203	        if shared.decode_overlap != CliDecodeOverlap::Off && shared.tp_size > 1 {
204	            return Err(CliError::rule(
205	                "--decode-overlap is single-GPU only; tp_size>1 has no prefill/decode overlap",
206	            ));
207	        }
208	        if cli.batch_invariant {
209	            if cli.enable_lora {
210	                return Err(CliError::rule(
211	                    "--batch-invariant is not supported with --enable-lora; enable one at a time",
212	                ));
213	            }
214	            if shared.decode_overlap != CliDecodeOverlap::Off {
215	                return Err(CliError::rule(
216	                    "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime",
217	                ));
218	            }
219	            if shared.kv_offload {
220	                return Err(CliError::rule(
221	                    "--batch-invariant is not supported with --kv-offload: offload keeps prefix matching \
222	                     on (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
223	                     shifts a prompt's chunk boundaries off the request-local grid",
224	                ));
225	            }
226	            if shared.dflash_draft_model_path.is_some() {
227	                return Err(CliError::rule(
228	                    "--batch-invariant is not supported with DFlash speculative decoding; enable one at a time",
229	                ));
230	            }
231	            if shared.tp_size > 1 {
232	                return Err(CliError::rule(
233	                    "--batch-invariant is not supported with --tp-size > 1; enable one at a time",
234	                ));
235	            }
236	            if !shared.no_prefix_cache {
237	                return Err(CliError::rule(
238	                    "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
239	                     boundaries off the request-local grid, so batch-invariant prefill cannot be provided",
240	                ));
241	            }
242	        }
243	        if shared.dflash_draft_model_path.is_some() {
244	            if cli.enable_lora {
245	                return Err(CliError::rule(
246	                    "--dflash-draft-model-path is not supported with --enable-lora",
247	                ));
248	            }
249	            if shared.kv_offload {
250	                return Err(CliError::rule(
251	                    "--dflash-draft-model-path is not supported with --kv-offload",
252	                ));
253	            }
254	            if shared.tp_size != 1 {
255	                return Err(CliError::rule(
256	                    "--dflash-draft-model-path currently requires --tp-size=1",
257	                ));
258	            }
259	        }
260	        if cli.eagle3_draft_model_path.is_some() {
261	            let conflicts = [
262	                (
263	                    shared.dflash_draft_model_path.is_some(),
264	                    "--dflash-draft-model-path",
265	                ),
266	                (cli.enable_lora, "--enable-lora"),
267	                (shared.kv_offload, "--kv-offload"),
268	                (
269	                    shared.decode_overlap != CliDecodeOverlap::Off,
270	                    "--decode-overlap",
271	                ),
272	                (cli.batch_invariant, "--batch-invariant"),
273	            ];
274	            if let Some((_, flag)) = conflicts.iter().find(|(set, _)| *set) {
275	                return Err(CliError::rule(format!(
276	                    "--eagle3-draft-model-path is not supported with {flag}"
277	                )));
278	            }
279	            if shared.tp_size != 1 {
280	                return Err(CliError::rule(
281	                    "--eagle3-draft-model-path currently requires --tp-size=1",
282	                ));
283	            }
284	        }
285	        Ok(())
286	    }
287	
288	    fn serve_plan(&self, ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
289	        let cli = cli(ctx);
290	        Ok(ServePlan {
291	            lora_modules: cli.enable_lora.then(|| cli.lora_modules.clone()),
292	            ..ServePlan::default()
293	        })
294	    }
295	
296	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
297	        let cli = cli(ctx);
298	        let shared = ctx.shared;
299	        let offload = if shared.kv_offload {
300	            let bytes = (shared.kv_offload_host_gib * f64::from(1u32 << 30)) as usize;
301	            let mut offload = Qwen3OffloadOptions::enabled(bytes);
302	            offload.use_hugepages = shared.kv_offload_hugepages;
303	            if let (Some(metaserver_addr), Some(advertise_addr)) = (
304	                shared.kv_p2p_metaserver_addr.clone(),
305	                shared.kv_p2p_advertise_addr.clone(),
306	            ) {
307	                offload = offload.with_p2p(Qwen3P2pOptions {
308	                    metaserver_addr,
309	                    advertise_addr,
310	                    rdma_nics: shared.kv_p2p_nics.clone(),
311	                    flush_on_finish: cli.kv_p2p_flush_on_finish,
312	                });
313	            }
314	            if let Some(seed) = cli.kv_pd_vllm_seed.clone() {
315	                offload = offload.with_vllm_compat(Qwen3VllmCompatOptions {
316	                    python_hash_seed: seed,
317	                    namespace: cli
318	                        .kv_pd_vllm_namespace
319	                        .clone()
320	                        .expect("clap requires kv_pd_vllm_namespace"),
321	                    miss_wait: std::time::Duration::from_millis(cli.kv_pd_miss_wait_ms),
322	                });
323	            }
324	            offload
325	        } else {
326	            Qwen3OffloadOptions::disabled()
327	        };
328	        let lora = cli.enable_lora.then_some(Qwen3LoraOptions {
329	            max_loras: cli.max_loras,
330	            max_lora_rank: cli.max_lora_rank,
331	        });
332	        let kv_cache_memory_margin_bytes = cli
333	            .kv_cache_memory_margin_mib
334	            .checked_mul(1 << 20)
335	            .ok_or_else(|| {
336	                anyhow::anyhow!(
337	                    "--kv-cache-memory-margin-mib is too large: {}",
338	                    cli.kv_cache_memory_margin_mib
339	                )
340	            })?;
341	        crate::launch(
342	            ctx.model_path,
343	            Qwen3LaunchOptions {
344	                device_ordinal: shared.device_ordinal,
345	                tp_size: shared.tp_size,
346	                cuda_graph: shared.cuda_graph,
347	                dump_graph_png: shared.dump_graph_png.clone(),
348	                offload,
349	                no_prefix_cache: shared.no_prefix_cache,
350	                max_prefill_tokens: shared
351	                    .max_prefill_tokens
352	                    .unwrap_or(crate::DEFAULT_MAX_PREFILL_TOKENS),
353	                memory: Qwen3MemoryOptions::new(
354	                    cli.gpu_memory_utilization,
355	                    kv_cache_memory_margin_bytes,
356	                    cli.kv_page_size,
357	                )
358	                .validate()?,
359	                lora,
360	                decode_overlap: resolve_decode_overlap(shared.decode_overlap, shared.decode_sm_pct),
361	                batch_invariant: cli.batch_invariant,
362	                dflash_draft_model_path: shared.dflash_draft_model_path.clone(),
363	                eagle3_draft_model_path: cli.eagle3_draft_model_path,
364	            },
365	        )
366	        .map(LaunchedEngine::Stepped)
367	    }
368	}
369	
370	fn parse_max_lora_rank_arg(value: &str) -> Result<usize, String> {
371	    let rank = value
372	        .parse::<usize>()
373	        .map_err(|error| format!("invalid --max-lora-rank: {error}"))?;
374	    if Qwen3LoraOptions::is_supported_max_lora_rank(rank) {
375	        Ok(rank)
376	    } else {
377	        Err(format!(
378	            "--max-lora-rank must be one of: {}",
379	            Qwen3LoraOptions::supported_max_lora_ranks_display()
380	        ))
381	    }
382	}
383	
384	/// PYTHONHASHSEED as vLLM accepts it: a decimal integer in [0, 4294967295].
385	/// An empty or malformed seed would derive a well-formed key space that can
386	/// never match the peer — a config error must fail here, not as slow requests.
387	fn parse_pythonhashseed(s: &str) -> Result<String, String> {
388	    if s.parse::<u32>().is_err() || s.starts_with('+') {
389	        return Err(format!(
390	            "PYTHONHASHSEED must be a decimal integer in [0, 4294967295], got {s:?}"
391	        ));
392	    }
393	    Ok(s.to_string())
394	}
395	
396	/// A pegaflow namespace digest: exactly 8 lowercase hex chars.
397	fn parse_pegaflow_namespace(s: &str) -> Result<String, String> {
398	    if s.len() != 8
399	        || !s
400	            .bytes()
401	            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
402	    {
403	        return Err(format!(
404	            "namespace must be an 8-char lowercase hex digest, got {s:?}"
405	        ));
406	    }
407	    Ok(s.to_string())
408	}
409	
410	#[cfg(test)]
411	mod tests {
412	    use pegainfer_frontend::model_line::parse_for_line;
413	
414	    use super::*;
415	
416	    fn validate_argv(argv: &[&str]) -> Result<(), CliError> {
417	        let (shared, matches, provided) =
418	            parse_for_line(&MODEL_LINE, argv).map_err(|error| CliError::rule(error.to_string()))?;
419	        let config = serde_json::json!({});
420	        let ctx = LaunchContext {
421	            model_path: std::path::Path::new("unused"),
422	            config: &config,
423	            shared: &shared,
424	            matches: &matches,
425	        };
426	        MODEL_LINE.validate(&ctx, &provided)
427	    }
428	
429	    #[test]
430	    fn probe_accepts_qwen3_identity() {
431	        let json = serde_json::json!({"model_type":"qwen3","architectures":["Qwen3ForCausalLM"]});
432	        MODEL_LINE.probe(&json).expect("qwen3 config should probe");
433	    }
434	
435	    #[test]
436	    fn probe_rejects_bad_architectures() {
437	        let json = serde_json::json!({"model_type":"qwen3","architectures":["SomethingElse"]});
438	        MODEL_LINE.probe(&json).unwrap_err();
439	    }
440	
441	    #[test]
442	    fn probe_rejects_foreign_model_type() {
443	        let json = serde_json::json!({"model_type":"glm_moe_dsa"});
444	        let reason = MODEL_LINE.probe(&json).unwrap_err();
445	        assert!(reason.contains("qwen3"), "{reason}");
446	    }
447	
448	    #[test]
449	    fn accepts_graph_png_dump() {
450	        validate_argv(&["pegainfer", "--dump-graph-png", "decode.png"])
451	            .expect("graph PNG dump with CUDA Graph enabled should validate");
452	    }
453	
454	    #[test]
455	    fn graph_png_dump_requires_cuda_graph() {
456	        let error = validate_argv(&[
457	            "pegainfer",
458	            "--dump-graph-png",
459	            "decode.png",
460	            "--cuda-graph=false",
461	        ])
462	        .expect_err("graph dump without CUDA Graph should be rejected");
463	        assert!(error.to_string().contains("requires --cuda-graph=true"));
464	    }
465	
466	    #[test]
467	    fn graph_png_dump_rejects_lora() {
468	        let error = validate_argv(&[
469	            "pegainfer",
470	            "--dump-graph-png",
471	            "decode.png",
472	            "--enable-lora",
473	        ])
474	        .expect_err("graph dump with LoRA should be rejected");
475	        assert!(
476	            error
477	                .to_string()
478	                .contains("not supported with --enable-lora")
479	        );
480	    }
481	
482	    #[test]
483	    fn eagle3_draft_rejects_unsupported_combinations() {
484	        validate_argv(&["pegainfer", "--eagle3-draft-model-path", "e"])
485	            .expect("EAGLE-3 alone should validate");
486	        for (extra, rule) in [
487	            (
488	                &["--dflash-draft-model-path", "d"][..],
489	                "--dflash-draft-model-path",
490	            ),
491	            (&["--enable-lora"][..], "--enable-lora"),
492	            (&["--kv-offload"][..], "--kv-offload"),
493	            (&["--tp-size", "2"][..], "--tp-size=1"),
494	        ] {
495	            let mut argv = vec!["pegainfer", "--eagle3-draft-model-path", "e"];
496	            argv.extend_from_slice(extra);
497	            let error = validate_argv(&argv).expect_err(rule);
498	            assert!(error.to_string().contains(rule), "{error}");
499	        }
500	    }
501	
502	    #[test]
503	    fn rejects_other_lines_flags() {
504	        let error =
505	            parse_for_line(&MODEL_LINE, &["pegainfer", "--dp-size", "8"]).expect_err("dp_size");
506	        assert!(
507	            error.to_string().contains("is not used by Qwen3"),
508	            "{error}"
509	        );
510	    }
511	
512	    #[test]
513	    fn parses_supported_max_lora_rank() {
514	        assert_eq!(parse_max_lora_rank_arg("16").expect("parse rank"), 16);
515	        assert_eq!(parse_max_lora_rank_arg("320").expect("parse rank"), 320);
516	    }
517	
518	    #[test]
519	    fn rejects_unsupported_max_lora_rank() {
520	        let error = parse_max_lora_rank_arg("7").expect_err("rank should be unsupported");
521	        assert!(error.contains("--max-lora-rank must be one of"));
522	        assert!(error.contains("16"));
523	    }
524	
525	    #[test]
526	    fn lora_default_rank_is_64() {
527	        assert_eq!(Qwen3LoraOptions::default().max_lora_rank, 64);
528	    }
529	}
