//! Qwen3's [`ModelLine`] implementation: config probing, the Qwen3-exclusive
//! CLI section, cross-flag rules, and launch-option assembly. The server
//! binary only sees `&MODEL_LINE`.

use std::collections::BTreeSet;
use std::path::PathBuf;

use clap::Args as ClapArgs;
use clap::FromArgMatches;
use pegainfer_frontend::engine::LaunchedEngine;
use pegainfer_frontend::model_line::ArgRequirement;
use pegainfer_frontend::model_line::CliDecodeOverlap;
use pegainfer_frontend::model_line::CliError;
use pegainfer_frontend::model_line::LaunchContext;
use pegainfer_frontend::model_line::ModelLine;
use pegainfer_frontend::model_line::ServePlan;
use pegainfer_frontend::vllm::LoraModule;
use pegainfer_frontend::vllm::parse_lora_modules_arg;

use crate::DecodeOverlap;
use crate::Qwen3LaunchOptions;
use crate::Qwen3LoraOptions;
use crate::Qwen3MemoryOptions;
use crate::Qwen3OffloadOptions;
use crate::Qwen3P2pOptions;
use crate::Qwen3VllmCompatOptions;

pub static MODEL_LINE: Qwen3Line = Qwen3Line;

pub struct Qwen3Line;

// Qwen3-exclusive CLI flags. Shared flags (`--tp-size`, `--kv-offload`, …)
// live in `SharedArgs`. (Regular comment: a doc comment would override the
// command about via clap's augment.)
#[derive(ClapArgs)]
#[allow(clippy::struct_excessive_bools)] // independent CLI flags, not a state machine
struct Qwen3Cli {
    /// Enable Qwen3 LoRA serving mode.
    #[arg(long, default_value_t = false)]
    enable_lora: bool,

    /// LoRA modules to load at startup. Accepts vLLM-style `name=path`, JSON
    /// object, or JSON list object entries with `name` and `path`.
    #[arg(long = "lora-modules", value_parser = parse_lora_modules_arg)]
    lora_modules: Vec<LoraModule>,

    /// Maximum number of resident LoRA adapters in Qwen3 LoRA mode.
    #[arg(long = "max-loras", default_value_t = Qwen3LoraOptions::DEFAULT_MAX_LORAS)]
    max_loras: usize,

    /// Maximum supported LoRA rank in Qwen3 LoRA mode.
    #[arg(long = "max-lora-rank", default_value_t = Qwen3LoraOptions::DEFAULT_MAX_LORA_RANK, value_parser = parse_max_lora_rank_arg)]
    max_lora_rank: usize,

    /// P/D prefill role: barrier each request's KV saves (host tier +
    /// MetaServer registration) before its final token event, so this
    /// instance's HTTP response doubles as the KV-ready signal a router can
    /// act on. Leave off on decode instances.
    #[arg(long, default_value_t = false)]
    kv_p2p_flush_on_finish: bool,

    /// P/D decode role with a vLLM prefill peer: the shared PYTHONHASHSEED
    /// value set on every vLLM prefill process. Switches offload query keys to
    /// vLLM's prefix-cache hash scheme (requires the P side to run
    /// --prefix-caching-hash-algo xxhash_cbor) and makes a cold request wait
    /// out the producer's registration tail instead of prefilling locally.
    /// Requires --kv-pd-vllm-namespace and the P2P mesh flags.
    #[arg(long, value_parser = parse_pythonhashseed)]
    kv_pd_vllm_seed: Option<String>,

    /// The vLLM prefill peer's pegaflow-connector namespace (an 8-hex digest
    /// the connector logs at startup as `namespace=...`). Both sides must
    /// address the same content domain. The digest carries no model identity:
    /// pointing a decode node at a different model's namespace (same
    /// tokenizer, same geometry class) silently cross-loads foreign KV.
    #[arg(long, value_parser = parse_pegaflow_namespace)]
    kv_pd_vllm_namespace: Option<String>,

    /// Zero-hit wait window for --kv-pd-vllm-seed mode, in milliseconds: how
    /// long a cold request keeps re-querying before giving up on the expected
    /// remote KV and prefilling locally. Must stay below the executor's 15s
    /// remote-fetch deadline (enforced at startup).
    #[arg(long, default_value_t = 5000)]
    kv_pd_miss_wait_ms: u64,

    /// Fraction of total GPU memory the Qwen3 instance may use. The KV cache is
    /// sized from this budget after startup profiling accounts for weights,
    /// runtime buffers, activation peak, margin, and (single-GPU only) CUDA-graph
    /// capture; tensor parallelism runs decode eagerly (no graph).
    #[arg(long, default_value_t = crate::DEFAULT_GPU_MEMORY_UTILIZATION)]
    gpu_memory_utilization: f64,

    /// Additional Qwen3 GPU memory to hold back after profile-based KV sizing,
    /// in MiB. Covers allocator fragmentation and small unprofiled drift.
    #[arg(long, default_value_t = (crate::DEFAULT_KV_CACHE_MEMORY_MARGIN_BYTES >> 20) as usize)]
    kv_cache_memory_margin_mib: usize,

    /// KV cache page (block) size in tokens. FlashInfer's paged attention only
    /// accepts a restricted set; 16 (default) or 64. Larger pages cut block
    /// bookkeeping overhead at the cost of coarser-grained allocation.
    #[arg(long, default_value_t = crate::DEFAULT_KV_PAGE_SIZE)]
    kv_page_size: usize,

    /// Enable single-GPU Qwen3 batch-invariant serving by pinning the numeric paths and cutting
    /// each prompt's prefill chunks on its own grid. Off by default. Requires `--no-prefix-cache`;
    /// incompatible with `--kv-offload`, which keeps prefix matching on regardless.
    #[arg(long, default_value_t = false)]
    batch_invariant: bool,

    /// EAGLE-3 drafter model path. A greedy request drafts while it is the only
    /// active request; larger batches decode plainly. Single-GPU only, not with
    /// --dflash-draft-model-path, --enable-lora, --kv-offload, --decode-overlap
    /// or --batch-invariant, and forces the prefix cache off.
    #[arg(long)]
    eagle3_draft_model_path: Option<PathBuf>,
}

fn resolve_decode_overlap(overlap: CliDecodeOverlap, decode_sm_pct: u32) -> DecodeOverlap {
    match overlap {
        CliDecodeOverlap::Off => DecodeOverlap::Off,
        CliDecodeOverlap::Stream => DecodeOverlap::SharedSm,
        CliDecodeOverlap::GreenCtx => DecodeOverlap::GreenCtx {
            decode_pct: decode_sm_pct,
        },
    }
}

fn cli(ctx: &LaunchContext<'_>) -> Qwen3Cli {
    Qwen3Cli::from_arg_matches(ctx.matches).expect("Qwen3Cli parses from the merged command")
}

impl ModelLine for Qwen3Line {
    fn name(&self) -> &'static str {
        "Qwen3"
    }

    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
        if model_type != Some("qwen3") {
            return Err(format!("model_type {model_type:?} is not \"qwen3\""));
        }
        crate::probe_config_json(config).map_err(|error| error.to_string())
    }

    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
        Qwen3Cli::augment_args(cmd)
    }

    fn consumed_shared_args(&self) -> &'static [&'static str] {
        &[
            "cuda_graph",
            "dump_graph_png",
            "device_ordinal",
            "tp_size",
            "kv_offload",
            "kv_offload_host_gib",
            "kv_offload_hugepages",
            "kv_p2p_metaserver_addr",
            "kv_p2p_advertise_addr",
            "kv_p2p_nics",
            "no_prefix_cache",
            "max_prefill_tokens",
            "dflash_draft_model_path",
            "decode_overlap",
            "decode_sm_pct",
        ]
    }

    fn arg_requirements(&self) -> &'static [ArgRequirement] {
        &[
            ("kv_p2p_flush_on_finish", &["kv_p2p_metaserver_addr"]),
            (
                "kv_pd_vllm_seed",
                &["kv_p2p_metaserver_addr", "kv_pd_vllm_namespace"],
            ),
            ("kv_pd_vllm_namespace", &["kv_pd_vllm_seed"]),
            ("kv_pd_miss_wait_ms", &["kv_pd_vllm_seed"]),
        ]
    }

    fn validate(
        &self,
        ctx: &LaunchContext<'_>,
        provided: &BTreeSet<String>,
    ) -> Result<(), CliError> {
        let cli = cli(ctx);
        let shared = ctx.shared;
        if !cli.enable_lora && !cli.lora_modules.is_empty() {
            return Err(CliError::rule("--lora-modules requires --enable-lora"));
        }
        if !cli.enable_lora
            && (provided.contains("max_loras") || provided.contains("max_lora_rank"))
        {
            return Err(CliError::rule(
                "--max-loras and --max-lora-rank require --enable-lora",
            ));
        }
        if shared.dump_graph_png.is_some() && cli.enable_lora {
            return Err(CliError::rule(
                "--dump-graph-png is not supported with --enable-lora (LoRA disables CUDA Graph)",
            ));
        }
        if shared.decode_overlap != CliDecodeOverlap::Off && shared.tp_size > 1 {
            return Err(CliError::rule(
                "--decode-overlap is single-GPU only; tp_size>1 has no prefill/decode overlap",
            ));
        }
        if cli.batch_invariant {
            if cli.enable_lora {
                return Err(CliError::rule(
                    "--batch-invariant is not supported with --enable-lora; enable one at a time",
                ));
            }
            if shared.decode_overlap != CliDecodeOverlap::Off {
                return Err(CliError::rule(
                    "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime",
                ));
            }
            if shared.kv_offload {
                return Err(CliError::rule(
                    "--batch-invariant is not supported with --kv-offload: offload keeps prefix matching \
                     on (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
                     shifts a prompt's chunk boundaries off the request-local grid",
                ));
            }
            if shared.dflash_draft_model_path.is_some() {
                return Err(CliError::rule(
                    "--batch-invariant is not supported with DFlash speculative decoding; enable one at a time",
                ));
            }
            if shared.tp_size > 1 {
                return Err(CliError::rule(
                    "--batch-invariant is not supported with --tp-size > 1; enable one at a time",
                ));
            }
            if !shared.no_prefix_cache {
                return Err(CliError::rule(
                    "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
                     boundaries off the request-local grid, so batch-invariant prefill cannot be provided",
                ));
            }
        }
        if shared.dflash_draft_model_path.is_some() {
            if cli.enable_lora {
                return Err(CliError::rule(
                    "--dflash-draft-model-path is not supported with --enable-lora",
                ));
            }
            if shared.kv_offload {
                return Err(CliError::rule(
                    "--dflash-draft-model-path is not supported with --kv-offload",
                ));
            }
            if shared.tp_size != 1 {
                return Err(CliError::rule(
                    "--dflash-draft-model-path currently requires --tp-size=1",
                ));
            }
        }
        if cli.eagle3_draft_model_path.is_some() {
            let conflicts = [
                (
                    shared.dflash_draft_model_path.is_some(),
                    "--dflash-draft-model-path",
                ),
                (cli.enable_lora, "--enable-lora"),
                (shared.kv_offload, "--kv-offload"),
                (
                    shared.decode_overlap != CliDecodeOverlap::Off,
                    "--decode-overlap",
                ),
                (cli.batch_invariant, "--batch-invariant"),
            ];
            if let Some((_, flag)) = conflicts.iter().find(|(set, _)| *set) {
                return Err(CliError::rule(format!(
                    "--eagle3-draft-model-path is not supported with {flag}"
                )));
            }
            if shared.tp_size != 1 {
                return Err(CliError::rule(
                    "--eagle3-draft-model-path currently requires --tp-size=1",
                ));
            }
        }
        Ok(())
    }

    fn serve_plan(&self, ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
        let cli = cli(ctx);
        Ok(ServePlan {
            lora_modules: cli.enable_lora.then(|| cli.lora_modules.clone()),
            ..ServePlan::default()
        })
    }

    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
        let cli = cli(ctx);
        let shared = ctx.shared;
        let offload = if shared.kv_offload {
            let bytes = (shared.kv_offload_host_gib * f64::from(1u32 << 30)) as usize;
            let mut offload = Qwen3OffloadOptions::enabled(bytes);
            offload.use_hugepages = shared.kv_offload_hugepages;
            if let (Some(metaserver_addr), Some(advertise_addr)) = (
                shared.kv_p2p_metaserver_addr.clone(),
                shared.kv_p2p_advertise_addr.clone(),
            ) {
                offload = offload.with_p2p(Qwen3P2pOptions {
                    metaserver_addr,
                    advertise_addr,
                    rdma_nics: shared.kv_p2p_nics.clone(),
                    flush_on_finish: cli.kv_p2p_flush_on_finish,
                });
            }
            if let Some(seed) = cli.kv_pd_vllm_seed.clone() {
                offload = offload.with_vllm_compat(Qwen3VllmCompatOptions {
                    python_hash_seed: seed,
                    namespace: cli
                        .kv_pd_vllm_namespace
                        .clone()
                        .expect("clap requires kv_pd_vllm_namespace"),
                    miss_wait: std::time::Duration::from_millis(cli.kv_pd_miss_wait_ms),
                });
            }
            offload
        } else {
            Qwen3OffloadOptions::disabled()
        };
        let lora = cli.enable_lora.then_some(Qwen3LoraOptions {
            max_loras: cli.max_loras,
            max_lora_rank: cli.max_lora_rank,
        });
        let kv_cache_memory_margin_bytes = cli
            .kv_cache_memory_margin_mib
            .checked_mul(1 << 20)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "--kv-cache-memory-margin-mib is too large: {}",
                    cli.kv_cache_memory_margin_mib
                )
            })?;
        crate::launch(
            ctx.model_path,
            Qwen3LaunchOptions {
                device_ordinal: shared.device_ordinal,
                tp_size: shared.tp_size,
                cuda_graph: shared.cuda_graph,
                dump_graph_png: shared.dump_graph_png.clone(),
                offload,
                no_prefix_cache: shared.no_prefix_cache,
                max_prefill_tokens: shared
                    .max_prefill_tokens
                    .unwrap_or(crate::DEFAULT_MAX_PREFILL_TOKENS),
                memory: Qwen3MemoryOptions::new(
                    cli.gpu_memory_utilization,
                    kv_cache_memory_margin_bytes,
                    cli.kv_page_size,
                )
                .validate()?,
                lora,
                decode_overlap: resolve_decode_overlap(shared.decode_overlap, shared.decode_sm_pct),
                batch_invariant: cli.batch_invariant,
                dflash_draft_model_path: shared.dflash_draft_model_path.clone(),
                eagle3_draft_model_path: cli.eagle3_draft_model_path,
            },
        )
        .map(LaunchedEngine::Stepped)
    }
}

fn parse_max_lora_rank_arg(value: &str) -> Result<usize, String> {
    let rank = value
        .parse::<usize>()
        .map_err(|error| format!("invalid --max-lora-rank: {error}"))?;
    if Qwen3LoraOptions::is_supported_max_lora_rank(rank) {
        Ok(rank)
    } else {
        Err(format!(
            "--max-lora-rank must be one of: {}",
            Qwen3LoraOptions::supported_max_lora_ranks_display()
        ))
    }
}

/// PYTHONHASHSEED as vLLM accepts it: a decimal integer in [0, 4294967295].
/// An empty or malformed seed would derive a well-formed key space that can
/// never match the peer — a config error must fail here, not as slow requests.
fn parse_pythonhashseed(s: &str) -> Result<String, String> {
    if s.parse::<u32>().is_err() || s.starts_with('+') {
        return Err(format!(
            "PYTHONHASHSEED must be a decimal integer in [0, 4294967295], got {s:?}"
        ));
    }
    Ok(s.to_string())
}

/// A pegaflow namespace digest: exactly 8 lowercase hex chars.
fn parse_pegaflow_namespace(s: &str) -> Result<String, String> {
    if s.len() != 8
        || !s
            .bytes()
            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
    {
        return Err(format!(
            "namespace must be an 8-char lowercase hex digest, got {s:?}"
        ));
    }
    Ok(s.to_string())
}

#[cfg(test)]
mod tests {
    use pegainfer_frontend::model_line::parse_for_line;

    use super::*;

    fn validate_argv(argv: &[&str]) -> Result<(), CliError> {
        let (shared, matches, provided) =
            parse_for_line(&MODEL_LINE, argv).map_err(|error| CliError::rule(error.to_string()))?;
        let config = serde_json::json!({});
        let ctx = LaunchContext {
            model_path: std::path::Path::new("unused"),
            config: &config,
            shared: &shared,
            matches: &matches,
        };
        MODEL_LINE.validate(&ctx, &provided)
    }

    #[test]
    fn probe_accepts_qwen3_identity() {
        let json = serde_json::json!({"model_type":"qwen3","architectures":["Qwen3ForCausalLM"]});
        MODEL_LINE.probe(&json).expect("qwen3 config should probe");
    }

    #[test]
    fn probe_rejects_bad_architectures() {
        let json = serde_json::json!({"model_type":"qwen3","architectures":["SomethingElse"]});
        MODEL_LINE.probe(&json).unwrap_err();
    }

    #[test]
    fn probe_rejects_foreign_model_type() {
        let json = serde_json::json!({"model_type":"glm_moe_dsa"});
        let reason = MODEL_LINE.probe(&json).unwrap_err();
        assert!(reason.contains("qwen3"), "{reason}");
    }

    #[test]
    fn accepts_graph_png_dump() {
        validate_argv(&["pegainfer", "--dump-graph-png", "decode.png"])
            .expect("graph PNG dump with CUDA Graph enabled should validate");
    }

    #[test]
    fn graph_png_dump_requires_cuda_graph() {
        let error = validate_argv(&[
            "pegainfer",
            "--dump-graph-png",
            "decode.png",
            "--cuda-graph=false",
        ])
        .expect_err("graph dump without CUDA Graph should be rejected");
        assert!(error.to_string().contains("requires --cuda-graph=true"));
    }

    #[test]
    fn graph_png_dump_rejects_lora() {
        let error = validate_argv(&[
            "pegainfer",
            "--dump-graph-png",
            "decode.png",
            "--enable-lora",
        ])
        .expect_err("graph dump with LoRA should be rejected");
        assert!(
            error
                .to_string()
                .contains("not supported with --enable-lora")
        );
    }

    #[test]
    fn eagle3_draft_rejects_unsupported_combinations() {
        validate_argv(&["pegainfer", "--eagle3-draft-model-path", "e"])
            .expect("EAGLE-3 alone should validate");
        for (extra, rule) in [
            (
                &["--dflash-draft-model-path", "d"][..],
                "--dflash-draft-model-path",
            ),
            (&["--enable-lora"][..], "--enable-lora"),
            (&["--kv-offload"][..], "--kv-offload"),
            (&["--tp-size", "2"][..], "--tp-size=1"),
        ] {
            let mut argv = vec!["pegainfer", "--eagle3-draft-model-path", "e"];
            argv.extend_from_slice(extra);
            let error = validate_argv(&argv).expect_err(rule);
            assert!(error.to_string().contains(rule), "{error}");
        }
    }

    #[test]
    fn rejects_other_lines_flags() {
        let error =
            parse_for_line(&MODEL_LINE, &["pegainfer", "--dp-size", "8"]).expect_err("dp_size");
        assert!(
            error.to_string().contains("is not used by Qwen3"),
            "{error}"
        );
    }

    #[test]
    fn parses_supported_max_lora_rank() {
        assert_eq!(parse_max_lora_rank_arg("16").expect("parse rank"), 16);
        assert_eq!(parse_max_lora_rank_arg("320").expect("parse rank"), 320);
    }

    #[test]
    fn rejects_unsupported_max_lora_rank() {
        let error = parse_max_lora_rank_arg("7").expect_err("rank should be unsupported");
        assert!(error.contains("--max-lora-rank must be one of"));
        assert!(error.contains("16"));
    }

    #[test]
    fn lora_default_rank_is_64() {
        assert_eq!(Qwen3LoraOptions::default().max_lora_rank, 64);
    }
}

//! The seam between the server binary and a model crate.
//!
//! A model line is everything south of the engine contract: config probing,
//! its own CLI knobs, and a `launch` that starts scheduler threads and hands
//! back a [`LaunchedEngine`]. The server binary holds a feature-gated
//! [`ModelLineRegistry`] and does pure dispatch — it never names a model
//! crate's option types.
//!
//! Onboarding a model line means implementing [`ModelLine`] in the model
//! crate and adding the instance to the registry in the server binary. No
//! other server edits: argument routing, consume-or-reject validation, and
//! config detection all derive from the trait.

use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::path::Path;
use std::path::PathBuf;

use vllm_chat::ParserSelection;

use crate::engine::LaunchedEngine;
use crate::vllm::LoraModule;

/// Model detection failed. The server branches on [`DetectError::NoMatch`]
/// to append a feature-gate hint for families that exist but were compiled
/// out; everything else just renders.
#[derive(Debug, thiserror::Error)]
pub enum DetectError {
    #[error("model config claimed by both {first} and {second}")]
    Conflict {
        first: &'static str,
        second: &'static str,
    },
    #[error(
        "no compiled-in model line claims this config (model_type={model_type}, architectures={architectures}); rejections: {}",
        rejections.join("; ")
    )]
    NoMatch {
        /// `model_type` from config.json, rendered verbatim (or `missing`).
        model_type: String,
        /// `architectures` from config.json, rendered verbatim (or `missing`).
        architectures: String,
        /// One `<line>: <reason>` entry per compiled-in line.
        rejections: Vec<String>,
    },
}

/// A CLI-level rejection: the flag set is well-formed for clap but invalid
/// for the detected model line.
#[derive(Debug, thiserror::Error)]
pub enum CliError {
    /// A provided flag is neither core, nor shared-and-consumed, nor one of
    /// the detected line's own flags.
    #[error("--{flag} is not used by {line}")]
    UnconsumedFlag { flag: String, line: &'static str },
    /// A line-specific cross-flag rule was violated. The message is the
    /// user-facing explanation; rules are prose, not a taxonomy.
    #[error("{0}")]
    Rule(String),
}

impl CliError {
    pub fn rule(message: impl Into<String>) -> Self {
        Self::Rule(message.into())
    }
}

/// Flags accepted for every model line regardless of detected type.
const CORE_ARGS: &[&str] = &[
    "model_path",
    "served_model_name",
    "port",
    "tool_call_parser",
];

/// A source argument id and the argument ids it requires.
pub type ArgRequirement = (&'static str, &'static [&'static str]);

const DEFAULT_MODEL_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../models/Qwen3-4B");

/// Shared CLI selector for model lines that can overlap prefill and decode.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, clap::ValueEnum)]
pub enum CliDecodeOverlap {
    /// One stream; prefill and decode serialize.
    #[default]
    Off,
    /// Two CUDA streams sharing all SMs.
    Stream,
    /// Green Context SM partition (SM-pinned streams).
    #[value(name = "green-ctx")]
    GreenCtx,
}

// CLI flags shared by more than one model line. Each line declares the
// subset it reads via `ModelLine::consumed_shared_args`; providing a flag
// outside that subset fails validation with a per-line error.
// (Regular comment: a doc comment here would override the command about.)
#[derive(Debug, clap::Args)]
#[allow(clippy::struct_excessive_bools)] // independent CLI flags, not a state machine
pub struct SharedArgs {
    /// Model directory containing config, tokenizer, and safetensor shards
    #[arg(long, default_value = DEFAULT_MODEL_PATH)]
    pub model_path: PathBuf,

    /// Public model ID returned by the OpenAI API (/v1/models, completion `model`).
    /// Defaults to the model path when omitted.
    #[arg(long)]
    pub served_model_name: Option<String>,

    /// Port to listen on
    #[arg(long, default_value_t = 8000)]
    pub port: u16,

    /// Tool-call output parser: `auto` (match the model), `none`, or an explicit
    /// registered parser name such as `qwen3_coder`. Upstream `auto` matches the
    /// model *path* by substring; a line whose checkpoints share one tool format
    /// can resolve `auto` to that parser itself (see `ServePlan`), so the
    /// directory name no longer decides.
    #[arg(long, default_value_t = ParserSelection::Auto)]
    pub tool_call_parser: ParserSelection,

    /// Enable CUDA Graph capture/replay on decode path (`--cuda-graph=false` to
    /// disable). Rejected for GLM5.2; forced off in Qwen3 LoRA mode; Qwen3.5
    /// always captures and rejects `false`; dense Gemma 4 captures per batch
    /// bucket while routed checkpoints warn and serve eagerly.
    #[arg(long, default_value_t = true, action = clap::ArgAction::Set)]
    pub cuda_graph: bool,

    /// Dump a live rank-0 decode CUDA Graph during startup. Qwen3 exports its
    /// batch-1 SplitKv graph; GLM5.2 exports EP bucket 1 selected by
    /// `--moe-topo`. Writes a complete sibling `.dot` for machine inspection
    /// and a folded Graphviz PNG at this path. Requires CUDA driver API 12.3
    /// or newer for kernel-name inspection.
    #[arg(long)]
    pub dump_graph_png: Option<PathBuf>,

    /// CUDA device ordinal for single-GPU Qwen3/Qwen3.5 loads
    #[arg(long, default_value_t = 0)]
    pub device_ordinal: usize,

    /// Tensor-parallel world size. GLM5.2 supports TP1/EP8 today; TP4/GB300
    /// bring-up uses --tp-size=4 --moe-topo=tp4.
    #[arg(long, default_value_t = 1)]
    pub tp_size: usize,

    /// Data-parallel world size. Kimi-K2 and GLM5.2 EP8 default to 8;
    /// GLM5.2 TP4 defaults to 1.
    #[arg(long)]
    pub dp_size: Option<usize>,

    /// Enable pegaflow KV offload (host-tier "L2" cache): single-GPU Qwen3,
    /// or GLM5.2 DP8 (one pool shared by all 8 ranks under one namespace).
    /// Sealed KV blocks are saved to host pinned memory and restored into
    /// HBM before prefill when a prompt's prefix has fallen out of the GPU
    /// cache. GLM5.2 requires the prefix cache: incompatible with
    /// --no-prefix-cache and speculative decoding.
    #[arg(long, default_value_t = false)]
    pub kv_offload: bool,

    /// Host pinned-memory pool size for the KV offload tier, in GiB. pegaflow
    /// allocates the whole pool up front, so RSS reflects this at startup.
    #[arg(long, default_value_t = 8.0, value_parser = parse_offload_gib)]
    pub kv_offload_host_gib: f64,

    /// Back the KV offload pool with 2 MiB hugepages. The box must hold a
    /// reservation covering the pool (`HugePages_Total` in /proc/meminfo;
    /// `echo N > /proc/sys/vm/nr_hugepages` as root) — allocation fails at
    /// startup otherwise.
    #[arg(long, default_value_t = false)]
    pub kv_offload_hugepages: bool,

    /// Join the cross-instance KV P2P mesh: pegaflow MetaServer gRPC address
    /// (e.g. `http://127.0.0.1:50056`). Saved block hashes register there and
    /// missing prefixes are pulled from peer instances over RDMA — the P/D
    /// disaggregation data plane. Requires --kv-offload, --kv-p2p-advertise-addr
    /// and --kv-p2p-nics.
    #[arg(long)]
    pub kv_p2p_metaserver_addr: Option<String>,

    /// This instance's routable IP:port for KV P2P — a literal socket address
    /// (it is also the embedded transfer-service bind address, so hostnames
    /// are rejected at startup). Peers dial it for RDMA handshakes and block
    /// queries. Must be reachable by every peer; not 0.0.0.0.
    #[arg(long)]
    pub kv_p2p_advertise_addr: Option<String>,

    /// RDMA NIC device names for KV P2P (e.g. `mlx5_0`), comma-separated.
    #[arg(long, value_delimiter = ',')]
    pub kv_p2p_nics: Vec<String>,

    /// vLLM-style no-prefix-cache. Without --kv-offload it disables prefix
    /// matching outright (every prefill recomputes the full prompt). With
    /// --kv-offload it is the pure-L2 mode: no cross-request HBM reuse, so every
    /// prefix is restored from the host tier — for measuring the L2 TTFT win.
    #[arg(long, default_value_t = false)]
    pub no_prefix_cache: bool,

    /// Speculative drafter model path: Qwen3 DFlash/DSpark decoding, or the
    /// GLM5.2 DSpark drafter (greedy AND sampled requests speculate;
    /// per-request accept stats logged). For Qwen3: single-GPU greedy only;
    /// incompatible with --enable-lora and --kv-offload, and forces the
    /// prefix cache off (it needs clean target hidden states).
    #[arg(long = "dflash-draft-model-path")]
    pub dflash_draft_model_path: Option<PathBuf>,

    /// Cap on total prompt tokens forwarded in one scheduler step. Qwen3 and
    /// Qwen3.5 only (rejected for other model lines); when omitted, they use
    /// their own crate defaults.
    #[arg(long)]
    pub max_prefill_tokens: Option<usize>,

    /// How prefill and decode share the GPU. Qwen3 supports `off`, `stream`,
    /// and `green-ctx`; Qwen3.5 supports `off` and `stream`.
    #[arg(long, value_enum, default_value_t = CliDecodeOverlap::Off)]
    pub decode_overlap: CliDecodeOverlap,

    /// Percent of SMs pinned to decode in `--decode-overlap green-ctx` (the rest
    /// go to prefill); rejected if set in any other mode.
    #[arg(long, default_value_t = 20, value_parser = clap::value_parser!(u32).range(1..=99))]
    pub decode_sm_pct: u32,
}

const SHARED_ARG_REQUIREMENTS: &[ArgRequirement] = &[
    ("kv_offload_host_gib", &["kv_offload"]),
    ("kv_offload_hugepages", &["kv_offload"]),
    (
        "kv_p2p_metaserver_addr",
        &["kv_offload", "kv_p2p_advertise_addr", "kv_p2p_nics"],
    ),
    ("kv_p2p_advertise_addr", &["kv_p2p_metaserver_addr"]),
    ("kv_p2p_nics", &["kv_p2p_metaserver_addr"]),
];

impl SharedArgs {
    /// Interactions between shared flags that hold for every consumer.
    /// Line-specific rules live in each line's [`ModelLine::validate`].
    pub fn validate(&self, provided: &BTreeSet<String>) -> Result<(), CliError> {
        if self.dump_graph_png.is_some() && !self.cuda_graph {
            return Err(CliError::rule(
                "--dump-graph-png requires --cuda-graph=true",
            ));
        }
        if provided.contains("device_ordinal") && self.tp_size > 1 {
            return Err(CliError::rule(
                "--device-ordinal is ignored under tensor parallelism; tp_size>1 uses devices 0..tp_size",
            ));
        }
        if provided.contains("decode_sm_pct") && self.decode_overlap != CliDecodeOverlap::GreenCtx {
            return Err(CliError::rule(
                "--decode-sm-pct only applies with --decode-overlap=green-ctx",
            ));
        }
        // An explicit parser name is taken verbatim by `FromStr`, so only the
        // registry can tell a typo from a real parser. Check it here, before an
        // engine load is spent on a request that could never be parsed.
        vllm_chat::validate_parser_overrides(&self.tool_call_parser, &ParserSelection::Auto)
            .map_err(|error| CliError::rule(format!("invalid --tool-call-parser: {error}")))?;
        Ok(())
    }
}

fn parse_offload_gib(value: &str) -> Result<f64, String> {
    let gib = value
        .parse::<f64>()
        .map_err(|error| format!("invalid --kv-offload-host-gib: {error}"))?;
    if gib.is_finite() && gib > 0.0 {
        Ok(gib)
    } else {
        Err("--kv-offload-host-gib must be a positive, finite number of GiB".to_owned())
    }
}

/// Everything `launch` and `serve_plan` may read.
pub struct LaunchContext<'a> {
    /// Model directory containing `config.json` and weights.
    pub model_path: &'a Path,
    /// Parsed `config.json` — the same value `probe` accepted.
    pub config: &'a serde_json::Value,
    /// Shared flags (the line reads only its consumed subset).
    pub shared: &'a SharedArgs,
    /// Full parse of the merged command; the line recovers its exclusive
    /// flags with `<Cli as clap::FromArgMatches>::from_arg_matches`.
    pub matches: &'a clap::ArgMatches,
}

/// What the frontend must know before (and independently of) the engine
/// finishing its load.
///
/// Lines should build their plan with `..ServePlan::default()` and spell only
/// what they set: CI compiles three model lines, so an exhaustive literal in
/// any other crate breaks on the next field added here and nothing catches it
/// until that crate is checked by hand.
pub struct ServePlan {
    /// Scheduler partitions (logical DP ranks) the launched engine will
    /// expose. The HTTP frontend registers one engine identity per partition
    /// *while the engine is still loading*, so this must be derivable from
    /// CLI flags alone. Checked against
    /// [`EngineHandle::scheduler_partition_count`] after launch.
    pub scheduler_partition_count: usize,
    /// Serve the prefill-only route contract (GLM5.2 TP4 P/D prefill role).
    pub prefill_only: bool,
    /// `Some` enables the LoRA routes, preloading the listed adapters.
    pub lora_modules: Option<Vec<LoraModule>>,
    /// The parser this line's tool syntax feeds, used when the caller leaves
    /// `--tool-call-parser` at `auto`. Upstream `Auto` matches the model
    /// *path* by substring, so it depends on the directory name; a line whose
    /// checkpoints share one tool format resolves `auto` itself instead.
    pub auto_tool_call_parser: Option<ParserSelection>,
}

impl ServePlan {
    /// The parser the server should run with: an explicit user selection wins;
    /// `auto` falls back to the line's own default when it declares one.
    pub fn resolve_tool_call_parser(&self, requested: ParserSelection) -> ParserSelection {
        match requested {
            ParserSelection::Auto => self
                .auto_tool_call_parser
                .clone()
                .unwrap_or(ParserSelection::Auto),
            explicit => explicit,
        }
    }
}

impl Default for ServePlan {
    fn default() -> Self {
        Self {
            scheduler_partition_count: 1,
            prefill_only: false,
            lora_modules: None,
            auto_tool_call_parser: None,
        }
    }
}

/// A servable model family. Implemented by each model crate.
pub trait ModelLine: Send + Sync {
    /// Family name used in logs, errors, and `--help` (e.g. `"Qwen3"`).
    fn name(&self) -> &'static str;

    /// Claim or reject a model directory by its parsed `config.json`.
    /// Return `Err` with the reason when the architecture doesn't match;
    /// exactly one registered line must accept a given config.
    fn probe(&self, config: &serde_json::Value) -> Result<(), String>;

    /// Append this line's exclusive CLI flags to the server command.
    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
        cmd
    }

    /// The [`SharedArgs`] ids this line reads. Providing any other shared
    /// flag with this line detected is an error.
    fn consumed_shared_args(&self) -> &'static [&'static str] {
        &[]
    }

    /// Unconditional requirements from this line's flags. Declare them here,
    /// not in Clap attributes, so release builds validate every referenced id.
    fn arg_requirements(&self) -> &'static [ArgRequirement] {
        &[]
    }

    /// Cross-flag rules beyond [`ModelLine::arg_requirements`]. Runs after the
    /// registry's consume-or-reject pass.
    fn validate(
        &self,
        _ctx: &LaunchContext<'_>,
        _provided: &BTreeSet<String>,
    ) -> Result<(), CliError> {
        Ok(())
    }

    /// Frontend-facing launch facts (partition count, prefill-only, LoRA).
    fn serve_plan(&self, _ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
        Ok(ServePlan::default())
    }

    /// Start the engine: spawn scheduler threads, build the handle with its
    /// metadata (`with_kv_capacity`, `with_metrics_watch`, ...), return it.
    /// Failures here are deep context chains (CUDA, weights, topology), not
    /// something callers branch on — hence `anyhow`.
    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine>;
}

struct LineEntry {
    line: &'static dyn ModelLine,
    own_ids: BTreeSet<String>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ArgOwner {
    Shared,
    Line(&'static str),
}

impl std::fmt::Display for ArgOwner {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Shared => f.write_str("SharedArgs"),
            Self::Line(name) => write!(f, "model line {name}"),
        }
    }
}

#[derive(Default)]
struct RegistryClaims {
    ids: BTreeMap<String, ArgOwner>,
    spellings: BTreeMap<String, ArgOwner>,
}

impl RegistryClaims {
    fn register_command(&mut self, command: &clap::Command, owner: ArgOwner) -> BTreeSet<String> {
        command
            .get_arguments()
            .map(|arg| self.register_arg(arg, owner))
            .collect()
    }

    fn register_arg(&mut self, arg: &clap::Arg, owner: ArgOwner) -> String {
        let id = arg.get_id().to_string();
        self.claim_id(id.clone(), owner);
        for long in arg
            .get_long()
            .into_iter()
            .chain(arg.get_all_aliases().into_iter().flatten())
        {
            self.claim_spelling(format!("--{long}"), owner);
        }
        for short in arg
            .get_short()
            .into_iter()
            .chain(arg.get_all_short_aliases().into_iter().flatten())
        {
            self.claim_spelling(format!("-{short}"), owner);
        }
        id
    }

    fn claim_id(&mut self, id: String, owner: ArgOwner) {
        if let Some(previous) = self.ids.get(&id) {
            if *previous == ArgOwner::Shared {
                if let ArgOwner::Line(name) = owner {
                    panic!(
                        "model line {name} redeclares SharedArgs flag id {id:?}; list it in consumed_shared_args instead"
                    );
                }
            }
            panic!("{previous} and {owner} both define flag id {id:?}");
        }
        self.ids.insert(id, owner);
    }

    fn claim_spelling(&mut self, spelling: String, owner: ArgOwner) {
        if let Some(previous) = self.spellings.get(&spelling) {
            panic!("{previous} and {owner} both define CLI spelling {spelling:?}");
        }
        self.spellings.insert(spelling, owner);
    }

    fn is_shared_id(&self, id: &str) -> bool {
        self.ids.get(id) == Some(&ArgOwner::Shared)
    }

    fn validate_requirement(&self, owner: ArgOwner, source: &str, targets: &[&str]) {
        assert!(
            self.ids.get(source) == Some(&owner),
            "{owner} declares requirements for unowned flag id {source:?}"
        );
        for &target in targets {
            assert!(source != target, "flag id {source:?} cannot require itself");
            let target_owner = self.ids.get(target);
            assert!(
                target_owner == Some(&ArgOwner::Shared) || target_owner == Some(&owner),
                "{owner} flag id {source:?} requires unknown or foreign argument id {target:?}"
            );
        }
    }
}

fn register_line(
    line: &'static dyn ModelLine,
    owner: ArgOwner,
    claims: &mut RegistryClaims,
) -> LineEntry {
    for id in line.consumed_shared_args() {
        assert!(
            claims.is_shared_id(id),
            "model line {} consumes unknown SharedArgs flag id {id:?}",
            line.name()
        );
    }
    let command = line.augment_cli(clap::Command::new("probe"));
    let own_ids = claims.register_command(&command, owner);
    LineEntry { line, own_ids }
}

/// The server binary's fixed list of compiled-in model lines.
pub struct ModelLineRegistry {
    entries: Vec<LineEntry>,
    requirements: BTreeMap<&'static str, &'static [&'static str]>,
}

impl ModelLineRegistry {
    /// Validates CLI ownership explicitly because Clap's equivalent schema
    /// assertions are disabled in release builds.
    pub fn new(lines: Vec<&'static dyn ModelLine>) -> Self {
        let shared_cmd = SharedArgs::augment_args(clap::Command::new("probe"));
        let mut claims = RegistryClaims::default();
        claims.register_command(&shared_cmd, ArgOwner::Shared);
        for id in CORE_ARGS {
            assert!(
                claims.is_shared_id(id),
                "CORE_ARGS contains unknown SharedArgs flag id {id:?}"
            );
        }
        let mut pending_requirements = SHARED_ARG_REQUIREMENTS
            .iter()
            .map(|&(source, targets)| (ArgOwner::Shared, source, targets))
            .collect::<Vec<_>>();
        let mut entries = Vec::with_capacity(lines.len());
        let mut line_names = BTreeSet::new();
        for line in lines {
            let name = line.name();
            assert!(
                line_names.insert(name),
                "duplicate model line name {name:?}"
            );
            let owner = ArgOwner::Line(name);
            entries.push(register_line(line, owner, &mut claims));
            pending_requirements.extend(
                line.arg_requirements()
                    .iter()
                    .map(|&(source, targets)| (owner, source, targets)),
            );
        }
        let mut requirements = BTreeMap::new();
        for (owner, source, targets) in pending_requirements {
            claims.validate_requirement(owner, source, targets);
            assert!(
                requirements.insert(source, targets).is_none(),
                "{owner} declares requirements more than once for flag id {source:?}"
            );
        }
        Self {
            entries,
            requirements,
        }
    }

    /// The full server command: shared flags plus every line's exclusive
    /// flags, so `--help` and parsing don't depend on the detected model.
    pub fn build_command(&self, cmd: clap::Command) -> clap::Command {
        let mut cmd = SharedArgs::augment_args(cmd);
        for entry in &self.entries {
            cmd = entry.line.augment_cli(cmd);
        }
        // `mut_arg` re-appends each source and would reorder `--help`.
        cmd.mut_args(|arg| {
            let Some(targets) = self.requirements.get(arg.get_id().as_str()) else {
                return arg;
            };
            arg.requires_all(targets.iter().copied())
        })
    }

    /// Find the unique line that claims this `config.json`. On
    /// [`DetectError::NoMatch`] the caller may prepend a hint for families
    /// that exist but were compiled out.
    pub fn detect(
        &self,
        config: &serde_json::Value,
    ) -> Result<&'static dyn ModelLine, DetectError> {
        let mut rejections = Vec::new();
        let mut claimed: Option<&'static dyn ModelLine> = None;
        for entry in &self.entries {
            match entry.line.probe(config) {
                Ok(()) => match claimed {
                    None => claimed = Some(entry.line),
                    Some(prev) => {
                        return Err(DetectError::Conflict {
                            first: prev.name(),
                            second: entry.line.name(),
                        });
                    }
                },
                Err(reason) => rejections.push(format!("{}: {reason}", entry.line.name())),
            }
        }
        claimed.ok_or_else(|| {
            let render = |key: &str| {
                config
                    .get(key)
                    .map_or_else(|| "missing".to_string(), std::string::ToString::to_string)
            };
            DetectError::NoMatch {
                model_type: render("model_type"),
                architectures: render("architectures"),
                rejections,
            }
        })
    }

    /// Consume-or-reject: every explicitly provided flag must be a core flag,
    /// a shared flag the detected line consumes, or one of the line's own.
    pub fn validate_provided(
        &self,
        detected: &'static dyn ModelLine,
        provided: &BTreeSet<String>,
        cmd: &clap::Command,
    ) -> Result<(), CliError> {
        let entry = self
            .entries
            .iter()
            .find(|entry| std::ptr::eq(entry.line, detected))
            .expect("detected line came from this registry");
        for id in provided {
            let id = id.as_str();
            if CORE_ARGS.contains(&id)
                || detected.consumed_shared_args().contains(&id)
                || entry.own_ids.contains(id)
            {
                continue;
            }
            return Err(CliError::UnconsumedFlag {
                flag: long_flag(cmd, id),
                line: detected.name(),
            });
        }
        Ok(())
    }
}

fn long_flag(cmd: &clap::Command, id: &str) -> String {
    cmd.get_arguments()
        .find(|arg| arg.get_id() == id)
        .and_then(clap::Arg::get_long)
        .map_or_else(|| id.to_owned(), str::to_owned)
}

/// Arg ids the user set explicitly (command line or env), for consume-or-reject.
pub fn provided_args(matches: &clap::ArgMatches, cmd: &clap::Command) -> BTreeSet<String> {
    // matches.ids() also yields clap's synthetic group ids; keep only real args.
    let real: BTreeSet<&str> = cmd
        .get_arguments()
        .map(|arg| arg.get_id().as_str())
        .collect();
    matches
        .ids()
        .map(clap::Id::as_str)
        .filter(|id| real.contains(id))
        .filter(|id| {
            matches!(
                matches.value_source(id),
                Some(
                    clap::parser::ValueSource::CommandLine | clap::parser::ValueSource::EnvVariable
                )
            )
        })
        .map(str::to_owned)
        .collect()
}

use clap::Args as _;

/// Test helper: parse `argv` against shared flags plus one line's flags, the
/// way the server binary does for a detected line. Exposed for model-crate
/// unit tests; not a serving entry point.
pub fn parse_for_line(
    line: &'static dyn ModelLine,
    argv: &[&str],
) -> anyhow::Result<(SharedArgs, clap::ArgMatches, BTreeSet<String>)> {
    use clap::FromArgMatches;
    let registry = ModelLineRegistry::new(vec![line]);
    let cmd = registry.build_command(clap::Command::new("pegainfer"));
    let matches = cmd.clone().try_get_matches_from(argv)?;
    let shared = SharedArgs::from_arg_matches(&matches)?;
    let provided = provided_args(&matches, &cmd);
    registry.validate_provided(line, &provided, &cmd)?;
    shared.validate(&provided)?;
    Ok((shared, matches, provided))
}

